declare(strict_types=1); namespace McpEmail\Tools;
final class GetSecuritySummaryTool implements ToolInterface {public function name():string{return 'get_security_summary';}public function definition():array{$s=(new ScanMailboxSecurityTool())->definition()['inputSchema'];$s['properties']['limit']['maximum']=100;return ['title'=>'Beveiligingssamenvatting','description'=>'Vat een begrensde periode samen met trends, authenticatiefouten, risicobijlagen en top-risicomails.','inputSchema'=>$s];}public function call(array $a):array{$a['include_safe']=true;$result=(new ScanMailboxSecurityTool())->call($a);if(!empty($result['isError']))return $result;$payload=json_decode($result['content'][0]['text'],true);$items=$payload['data']['suspicious_emails']??[];$domains=[];$terms=[];$days=[];foreach($items as $i){if(preg_match('/@([A-Z0-9.-]+)/i',$i['from'],$m))$domains[strtolower($m[1])]=($domains[strtolower($m[1])]??0)+1;$day=substr((string)$i['date'],0,10);$days[$day]=($days[$day]??0)+1;foreach($i['top_signals'] as $s)$terms[$s['code']]=($terms[$s['code']]??0)+1;}arsort($domains);arsort($terms);usort($items,fn($x,$y)=>$y['score']<=>$x['score']);return Support::apiSuccess(['scan'=>$payload['data']['counts'],'suspicious_sender_domains'=>array_slice($domains,0,10,true),'common_signals'=>array_slice($terms,0,10,true),'trends_per_day'=>$days,'top_risk_emails'=>array_slice($items,0,10),'possible_duplicates'=>'Niet bepaald zonder persistente inhoudsindex.'], $payload['meta']??[]);}}
